def transform(grid):
    g = np.array(grid)
    segs = []
    for y in range(g.shape[0]):
        for x in range(g.shape[1]):
            if g[y, x] == 1:
                xs = [x2 for x2 in range(x + 1, g.shape[1]) if g[y, x2] == 8]
                if xs:
                    segs.append((y, x, xs[0], g[y, x + 1:xs[0]].copy()))
    w = max(len(s[3]) for s in segs)
    out = np.zeros((len(segs), w), dtype=int)
    emit(out, f"Allocate a {len(segs)}x{w} canvas: one row per 1->8 pair, width = gap between them.")
    for i, (y, x1, x8, s) in enumerate(segs):
        out[i, :len(s)] = s
        emit(out, f"Row {i}: copy cells between the 1 at ({y},{x1}) and the 8 at ({y},{x8}).")
    emit(out, "All segments stacked in reading order; this is the output.")
    return out
